 put(p,kb.front(m)+b)
 ep=base/f'documents/{SID}/diagrams/{fid}.md';em,eb=kb.metadata(ep);em.update(canonical_diagram=x['path'],disposition='source-reconstruction',review_status=x['review_status'],visual_review=x['visual_review'],render_status='pass');tag='FUNDS-PROCESS';eb=re.sub(r'\n<!-- '+tag+' -->.*','',eb,flags=re.S);put(ep,kb.front(em)+eb+'\n<!-- '+tag+' -->\n'+kb.link(ep,p,'Canonical source reconstruction and review evidence')+'\n')
